@@ -1,181 +0,0 @@
-#define _POSIX_C_SOURCE 200809L
-
-#include "sepder.h"
-
-#include <errno.h>
-#include <getopt.h>
-#include <stdio.h>
-#include <stdlib.h>
-#include <string.h>
-#include <time.h>
-
-typedef struct
-{
-    struct timespec started;
-    struct timespec last_report;
-} progress_state_t;
-
-static double
-seconds_between(const struct timespec *start, const struct timespec *end)
-{
-    return (double) (end->tv_sec - start->tv_sec)
-        + 1.0e-9 * (double) (end->tv_nsec - start->tv_nsec);
-}
-
-static void
-report_progress(slong completed, slong target, void *context)
-{
-    progress_state_t *state = context;
-    struct timespec now;
-    double since_last;
-
-    clock_gettime(CLOCK_MONOTONIC, &now);
-    since_last = seconds_between(&state->last_report, &now);
-    if (completed != 1 && completed != target && since_last < 1.0)
-        return;
-
-    flint_fprintf(stderr,
-                  "completed %wd/%wd (%.1f seconds)\n",
-                  completed,
-                  target,
-                  seconds_between(&state->started, &now));
-    state->last_report = now;
-}
-
-static void
-print_usage(FILE *stream, const char *program)
-{
-    fprintf(stream,
-            "Usage: %s [--diagnostics] [--progress] N\n"
-            "\n"
-            "Compute b[0] through b[N], the numbers of separable "
-            "derangements.\n"
-            "\n"
-            "  --diagnostics  print n, s[n], a[n,0], and b[n] as TSV\n"
-            "  --progress     report rate-limited progress on stderr\n"
-            "  --help         show this help text\n"
-            "\n"
-            "OpenMP honors its normal environment variables, including "
-            "OMP_NUM_THREADS.\n",
-            program);
-}
-
-static int
-parse_max_n(const char *text, slong *max_n)
-{
-    char *end = NULL;
-    long parsed;
-
-    errno = 0;
-    parsed = strtol(text, &end, 10);
-    if (errno != 0 || end == text || *end != '\0' || parsed < 0)
-        return 0;
-    *max_n = (slong) parsed;
-    return (long) *max_n == parsed;
-}
-
-static int
-print_results(const sd_result_t *result, int diagnostics)
-{
-    slong n;
-
-    if (diagnostics)
-        fputs("n\ts_n\ta_n_0\tb_n\n", stdout);
-
-    for (n = 0; n <= result->max_n; ++n)
-    {
-        if (diagnostics)
-        {
-            flint_fprintf(stdout, "%wd\t", n);
-            fmpz_fprint(stdout, result->s + n);
-            fputc('\t', stdout);
-            fmpz_fprint(stdout, result->a0 + n);
-            fputc('\t', stdout);
-            fmpz_fprint(stdout, result->b + n);
-        }
-        else
-        {
-            fmpz_fprint(stdout, result->b + n);
-        }
-        fputc('\n', stdout);
-    }
-
-    return ferror(stdout) == 0;
-}
-
-int
-main(int argc, char **argv)
-{
-    static const struct option long_options[] = {
-        {"diagnostics", no_argument, NULL, 'd'},
-        {"progress", no_argument, NULL, 'p'},
-        {"help", no_argument, NULL, 'h'},
-        {NULL, 0, NULL, 0}
-    };
-    sd_result_t result;
-    progress_state_t progress_state;
-    sd_progress_fn progress_callback = NULL;
-    slong max_n;
-    int diagnostics = 0;
-    int progress = 0;
-    int option;
-    int status;
-    int exit_status = EXIT_FAILURE;
-
-    while ((option = getopt_long(argc, argv, "dph", long_options, NULL)) != -1)
-    {
-        switch (option)
-        {
-            case 'd':
-                diagnostics = 1;
-                break;
-            case 'p':
-                progress = 1;
-                break;
-            case 'h':
-                print_usage(stdout, argv[0]);
-                return EXIT_SUCCESS;
-            default:
-                print_usage(stderr, argv[0]);
-                return EXIT_FAILURE;
-        }
-    }
-
-    if (optind + 1 != argc || !parse_max_n(argv[optind], &max_n))
-    {
-        fprintf(stderr, "error: N must be one nonnegative decimal integer\n");
-        print_usage(stderr, argv[0]);
-        return EXIT_FAILURE;
-    }
-
-    if (progress)
-    {
-        clock_gettime(CLOCK_MONOTONIC, &progress_state.started);
-        progress_state.last_report = progress_state.started;
-        progress_callback = report_progress;
-    }
-
-    sd_result_init(&result);
-    status = sd_compute(&result,
-                        max_n,
-                        progress_callback,
-                        progress ? &progress_state : NULL);
-    if (status != SD_SUCCESS)
-    {
-        fprintf(stderr, "error: %s\n", sd_error_string(status));
-        goto cleanup;
-    }
-
-    if (!print_results(&result, diagnostics))
-    {
-        fprintf(stderr, "error: could not write complete output\n");
-        goto cleanup;
-    }
-
-    exit_status = EXIT_SUCCESS;
-
-cleanup:
-    sd_result_clear(&result);
-    flint_cleanup_master();
-    return exit_status;
-}

@@ -1,36 +0,0 @@
-#ifndef SEPDER_INTERNAL_H
-#define SEPDER_INTERNAL_H
-
-#include "sepder.h"
-
-typedef struct
-{
-    slong n;
