-
-#endif

@@ -1,107 +0,0 @@
-#include "sepder_internal.h"
-
-#include <errno.h>
-#include <limits.h>
-#include <stdio.h>
-#include <stdlib.h>
-
-typedef struct
-{
-    slong requested_n;
-} dump_context_t;
-
-static void
-print_scalar(const char *kind, slong n, const fmpz *value)
-{
-    flint_printf("%s\t%wd\t", kind, n);
-    fmpz_print(value);
-    putchar('\n');
-}
-
-static void
-print_diagonal(const char *kind, slong n, slong k, const fmpz *value)
-{
-    flint_printf("%s\t%wd\t%wd\t", kind, n, k);
-    fmpz_print(value);
-    putchar('\n');
-}
-
-static int
-dump_row(const sd_row_view_t *row, void *context)
-{
-    dump_context_t *dump_context = context;
-    slong k;
-    fmpz_t occupied;
-
-    if (row->n > dump_context->requested_n)
-        return 1;
-
-    if (row->diagonal_count != row->n)
-    {
-        flint_fprintf(stderr,
-                      "test horizon did not retain all diagonals at n=%wd\n",
-                      row->n);
-        return 0;
-    }
-
-    print_scalar("S", row->n, row->s);
-    print_scalar("SP", row->n, row->s_plus);
-    print_scalar("SM", row->n, row->s_minus);
-    fmpz_init(occupied);
-    for (k = -(row->n - 1); k <= row->n - 1; ++k)
-    {
-        slong offset = FLINT_ABS(k);
-        fmpz_sub(occupied, row->s, row->d + offset);
-        print_diagonal("A", row->n, k, occupied);
-        fmpz_sub(occupied, row->s_plus, row->d_plus + offset);
-        print_diagonal("AP", row->n, k, occupied);
-        fmpz_sub(occupied, row->s_minus, row->d_minus + offset);
-        print_diagonal("AM", row->n, k, occupied);
-    }
-    fmpz_clear(occupied);
-    return ferror(stdout) == 0;
-}
-
-int
-main(int argc, char **argv)
-{
-    sd_result_t result;
-    dump_context_t dump_context;
-    char *end = NULL;
-    long parsed;
-    slong horizon;
-    int status;
-
-    if (argc != 2)
-    {
-        fprintf(stderr, "Usage: %s N\n", argv[0]);
-        return EXIT_FAILURE;
-    }
-
-    errno = 0;
-    parsed = strtol(argv[1], &end, 10);
-    if (errno != 0 || end == argv[1] || *end != '\0' || parsed < 1)
-    {
-        fprintf(stderr, "N must be a positive integer\n");
